(() => {
  'use strict';
  const protectedModel = {"s":"WEQhIxNXgEHnoeWlW7K1gQ==","iv":"D1xmQX6Fpon4bZlG","data":""};
  const button = document.createElement('button');
  button.className = 'btn btn-ghost';
  button.textContent = 'Análise por vídeo';
  const anchor = document.querySelector('button[onclick="addSheetHere()"]');
  if (!anchor) return;
  anchor.after(button);

  function seconds(row) {
    const number = (v, fallback) => v == null || v === '' ? fallback : Number(String(v).replace(',', '.'));
    return number(row.tmu, 0) * number(row.q, 1) * number(row.f, 1) * 0.036;
  }
  function profile(samples, start, end) {
    const subset = samples.filter(sample => sample.t >= start && sample.t < end);
    return [0,1,2,3].map(i => subset.reduce((sum,s) => sum+s.z[i],0) / Math.max(1,subset.length));
  }
  function waitMedia(video,event,act,signal) {
    return new Promise((resolve,reject)=>{
      const done = error => {
        clearTimeout(timer);
        video.removeEventListener(event,ok);
        video.removeEventListener('error',fail);
        signal.removeEventListener('abort',fail);
        if(error) reject(error); else resolve();
      };
      const ok=()=>done(), fail=()=>done(new Error('A leitura do vídeo foi interrompida.'));
      const timer=setTimeout(fail,15000);
      video.addEventListener(event,ok,{once:true});
      video.addEventListener('error',fail,{once:true});
      signal.addEventListener('abort',fail,{once:true});
      if(signal.aborted){fail();return;}
      try{act();}catch(error){done(error);}
    });
  }
  async function scan(video,signal,status) {
    const canvas=document.createElement('canvas');
    canvas.width=32;canvas.height=24;
    const ctx=canvas.getContext('2d',{willReadFrequently:true});
    const count=Math.min(2400,Math.max(2,Math.ceil(video.duration*4)));
    const samples=[];
    let previous;
    for(let i=0;i<count;i++){
      const t=(i+0.5)*video.duration/count;
      await waitMedia(video,'seeked',()=>{video.currentTime=t;},signal);
      ctx.drawImage(video,0,0,32,24);
      const pixels=ctx.getImageData(0,0,32,24).data;
      const z=[0,0,0,0];
      if(previous) for(let p=0;p<768;p++){
        const offset=p*4, zone=(p%32>=16?1:0)+(p>=384?2:0);
        z[zone]+=Math.abs(pixels[offset+1]-previous[offset+1])/(192*255);
      }
      samples.push({t,z,motion:z.reduce((a,b)=>a+b,0)/4});
      previous=pixels;
      if(i%8===0) status.textContent='Lendo vídeo no computador: '+Math.round(100*i/count)+'%';
    }
    return samples;
  }
  button.onclick=()=>{
    const project=getActiveProject();
    if(!project){alert('Abra uma pasta e um projeto antes de selecionar o vídeo.');return;}
    const folderId=activeProjectCtx.folderId, projectId=project.id;
    const sameProject=()=>activeProjectCtx?.folderId===folderId && getActiveProject()?.id===projectId;
    const dialog=document.createElement('dialog');
    dialog.className='video-access';
    dialog.setAttribute('aria-labelledby','video-access-title');
    dialog.innerHTML=`
      <style>
        dialog.video-access {
          box-sizing:border-box; margin:auto; width:min(420px,calc(100% - 24px)); max-height:88vh;
          overflow:auto; padding:clamp(18px,4vw,28px); border:1px solid #344c66; border-radius:16px;
          background:#0d2034; color:#edf5ff; box-shadow:0 20px 64px #0006; font:inherit;
        }
        dialog.video-access[data-open] { width:min(720px,calc(100% - 24px)) }
        .video-access::backdrop { background:rgba(3,12,24,.74) }
        .video-access header { position:static; display:flex; align-items:flex-start; justify-content:space-between; gap:12px; background:none; padding:0 }
        .video-access h3 { margin:0; font-size:1.3rem }
        .video-access [data-scope] { margin:6px 0 20px; color:#b8cbe0; overflow-wrap:anywhere }
        .video-access button { cursor:pointer; font:inherit }
        .video-access [data-close] { background:transparent; color:#c2d6eb; border:0; padding:6px; border-radius:6px }
        .video-access form { display:grid; gap:8px }
        .video-access form[hidden] { display:none }
        .video-access label { font-weight:600 }
        .video-access .password-box { display:flex; background:#091827; border:1px solid #617b95; border-radius:9px; overflow:hidden }
        .video-access .password-box:focus-within { outline:2px solid #78c6ff; outline-offset:2px }
        .video-access .password-box input { min-width:0; width:100%; padding:12px; font:inherit; color:#fff; background:transparent; border:0; outline:none }
        .video-access [data-eye] { display:grid; place-items:center; flex:0 0 46px; background:transparent; color:#c9dcf0; border:0 }
        .video-access button:focus-visible { outline:2px solid #94d6ff; outline-offset:-3px }
        .video-access [data-eye][aria-pressed="false"] line { display:none }
        .video-access [type=submit] { margin-top:8px; min-height:44px; border:0; border-radius:9px; background:#89ceff; color:#081c30; font-weight:700 }
        .video-access [role=status] { margin:12px 0 0 }
        .video-access [role=status]:empty { margin:0 }
        .video-access form:not([hidden]) ~ [role=status] { color:#ffbbb5 }
      </style>
      <header><h3 id="video-access-title">Análise por vídeo</h3><button type="button" data-close>Fechar</button></header>
      <p data-scope></p>
      <form>
        <label for="video-access-password">Senha da atividade</label>
        <div class="password-box">
          <input id="video-access-password" type="password" required autocomplete="off" autofocus aria-describedby="video-access-status">
          <button type="button" data-eye aria-label="Mostrar senha" title="Mostrar senha" aria-pressed="false">
            <svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" aria-hidden="true">
              <path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/><line x1="3" y1="3" x2="21" y2="21"/>
            </svg>
          </button>
        </div>
        <button type="submit">Entrar</button>
      </form>
      <section hidden><label>Vídeo da operação <input type="file" accept="video/*"></label><video playsinline controls style="display:block;width:100%;max-height:220px;margin:12px 0"></video><div data-review></div></section>
      <p id="video-access-status" role="status"></p>`;
    document.body.append(dialog);
    dialog.querySelector('[data-scope]').textContent=pmData[folderId].name+' / '+project.name;
    const form=dialog.querySelector('form'), section=dialog.querySelector('section'), status=dialog.querySelector('[role=status]');
    const video=section.querySelector('video'), fileInput=section.querySelector('input'), review=section.querySelector('[data-review]');
    let url,controller,propose;
    const lock=new AbortController();
    dialog.querySelector('[data-close]').onclick=()=>dialog.close();
    dialog.onclose=()=>{lock.abort();controller?.abort();video.pause();video.removeAttribute('src');video.load();if(url) URL.revokeObjectURL(url);dialog.remove();};
    const field=form.querySelector('input'), eye=form.querySelector('[data-eye]');
    function showPassword(visible){
      field.type=visible?'text':'password';
      eye.setAttribute('aria-pressed',String(visible));
      eye.title=visible?'Ocultar senha':'Mostrar senha';
    }
    eye.onclick=()=>showPassword(field.type==='password');
    field.oninput=()=>{status.textContent='';};
    form.onsubmit=async e=>{
      e.preventDefault();
      if(!crypto.subtle){status.textContent='Abra o sistema por HTTPS ou localhost para usar a senha.';return;}
      showPassword(false);
      const bytes = value => Uint8Array.from(atob(value), c=>c.charCodeAt(0));
      try {
        const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(field.value),'PBKDF2',false,['deriveKey']);
        field.value='';
        const key=await crypto.subtle.deriveKey({name:'PBKDF2',hash:'SHA-256',iterations:600000,salt:bytes(protectedModel.s)},material,{name:'AES-GCM',length:256},false,['decrypt']);
        const source=await crypto.subtle.decrypt({name:'AES-GCM',iv:bytes(protectedModel.iv)},key,bytes(protectedModel.data));
        const modelUrl=URL.createObjectURL(new Blob([source],{type:'text/javascript'}));
        try { propose=(await import(modelUrl)).propose; } finally { URL.revokeObjectURL(modelUrl); }
      } catch(error) {
        status.textContent=error.name==='OperationError'?'Senha incorreta.':'Falha ao abrir o módulo de análise.';
        field.focus();return;
      }
      if(lock.signal.aborted)return;
      form.hidden=true;dialog.setAttribute('data-open','');
      section.hidden=false;status.textContent='Selecione o vídeo para iniciar.';
      for(const sheet of scopedSheets()){
        const report=sheet.header?.videoMtm;
        if(!Array.isArray(report?.segments))continue;
        const details=document.createElement('details'),title=document.createElement('summary');
        title.textContent=sheet.label+' · '+Number(report.duration).toFixed(2)+' s';
        details.append(title);
        for(const segment of report.segments){
          const row=sheet.rows.find(r=>r.id===segment.rowId);if(!row)continue;
          const p=document.createElement('p');
          p.textContent=Number(segment.start).toFixed(2)+' a '+Number(segment.end).toFixed(2)+' s | '+row.desc+' | Trecho '+(segment.end-segment.start).toFixed(2)+' s | MTM '+seconds(row).toFixed(2)+' s';
          details.append(p);
        }
        section.append(details);
      }
    };
    fileInput.onchange=async()=>{
      if(!propose||!sameProject())return;
      const file=fileInput.files[0];if(!file)return;
      controller?.abort();controller=new AbortController();
      const signal=controller.signal;
      review.replaceChildren();
      video.pause();if(url)URL.revokeObjectURL(url);
      url=URL.createObjectURL(file);
      const history=scopedSheets().filter(s=>s.rows.some(r=>r.code&&r.desc&&seconds(r)>0));
      try{
        if(!history.length)throw new Error('Este projeto precisa de pelo menos uma folha com atividade, código e tempo MTM para sugerir uma sequência.');
        video.controls=false;
        await waitMedia(video,'loadeddata',()=>{video.src=url;video.load();},signal);
        if(!Number.isFinite(video.duration)||video.duration<=0)throw new Error('O arquivo não tem duração legível.');
        const samples=await scan(video,signal,status);
        const result=propose(history,samples,video.duration);
        video.controls=true;video.currentTime=0;
        status.textContent='Prévia gerada. Confira as atividades e os limites antes de gravar.';
        const intro=document.createElement('p');
        intro.textContent='Referência: '+result.label+'. A sequência e os códigos são sugestões do histórico. Os cortes são estimados pela variação de movimento no vídeo.';
        review.append(intro);
        const choices=new Map();
        for(const sheet of history)for(const r of sheet.rows)if(r.code&&r.desc&&seconds(r)>0) choices.set(JSON.stringify([r.desc,r.code,r.q,r.f,r.tmu,r.agrega]),r);
        const entries=[...choices.values()];
        const editors=[];
        function addEditor(seg, after){
          const line=document.createElement('div');
          line.style.cssText='display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:7px 0';
          const play=document.createElement('button');play.textContent='Ver trecho';
          const select=document.createElement('select');select.style.maxWidth='100%';
          select.setAttribute('aria-label','Atividade do trecho');
          entries.forEach((r,j)=>select.add(new Option(r.desc+' ('+r.code+')',j)));
          const match=entries.findIndex(r=>['desc','code','q','f','tmu','agrega'].every(k=>r[k]===seg.row[k]));
          select.value=String(match);
          const end=document.createElement('input');end.type='number';end.step='any';end.style.width='85px';
          end.value=String(seg.end);end.disabled=false;
          const label=document.createElement('label');label.textContent='Fim (s) ';label.append(end);
          const metric=document.createElement('small');
          const update=()=>{editors.forEach((ed,j)=>{ed.end.disabled=j===editors.length-1;ed.metric.textContent='Trecho '+(Number(ed.end.value)-(j?Number(editors[j-1].end.value):0)).toFixed(2)+' s | MTM '+seconds(entries[Number(ed.select.value)]).toFixed(2)+' s';});};
          const item={select,end,metric,line};
          if(after){
            editors.splice(editors.indexOf(after)+1,0,item);after.line.after(line);
          }else{ editors.push(item);review.append(line); }
          const startTime=()=>{const idx=editors.indexOf(item);return idx?Number(editors[idx-1].end.value):0;};
          play.onclick=()=>{video.currentTime=startTime();video.pause();};
          const split=document.createElement('button');split.textContent='Dividir';
          split.onclick=()=>{
            const old=Number(end.value),start=startTime();
            if(!(old>start))return;
            end.value=String(video.currentTime>start && video.currentTime<old ? video.currentTime : (old+start)/2);
            addEditor({row:entries[Number(select.value)],end:old},item);
          };
          const merge=document.createElement('button');merge.textContent='Unir ao próximo';
          merge.onclick=()=>{
            const idx=editors.indexOf(item),next=editors[idx+1];if(!next)return;
            end.value=next.end.value;editors.splice(idx+1,1);next.line.remove();update();
          };
          select.onchange=update;end.oninput=update;line.append(play,select,label,metric,split,merge);update();
        }
        for(const seg of result.segments)addEditor(seg);
        const save=document.createElement('button');save.textContent='Gravar análise no projeto';
        review.append(save);
        save.onclick=()=>{
          if(!sameProject()){status.textContent='Abra novamente o projeto de origem.';return;}
          let start=0;
          const id=gid(),rows=[],segments=[];
          for(const ed of editors){
            const end=Number(ed.end.value);
            if(!ed.end.value||!(end>start)||end>video.duration){status.textContent='Confira a sequência dos tempos finais.';return;}
            const row={...entries[Number(ed.select.value)],id:'r_'+id+'_'+rows.length};
            rows.push(row);segments.push({rowId:row.id,start,end,features:profile(samples,start,end)});start=end;
          }
          const header={empresa:pmData[folderId].name,projeto:project.name,videoMtm:{filename:file.name,duration:video.duration,segments}};
          sheets.push({id,label:'Vídeo '+file.name,rows,header,book:'',fadiga:null});
          attachSheetToActiveProject(id);saveSheets();save.disabled=true;renderTabs();setActive(id);dialog.close();
        };
      }catch(error){if(!signal.aborted){video.controls=true;status.textContent=error.message;}}
    };
    dialog.showModal();
  };
})();